import pathlib,json,hashlib,collections,datetime
R=pathlib.Path(__file__).resolve().parent
def read(n):return json.loads((R/'verification'/n).read_text())
def save(n,x):(R/'verification'/n).write_text(json.dumps(x,indent=2),encoding='utf-8')
s=read('summary.json');a=read('final-integrity.json');q=read('diagnosis-summary.json');u=read('usage.json');rows=read('scores.json')
def cost(v):return ((v['inputTokenCount']-v['cachedInputTokenCount'])*.25+v['cachedInputTokenCount']*.025+v['outputTokenCount']*2)/1e6
costs={k:cost(v) for k,v in u.items()};costs['split']=costs['source']+costs['editorial'];costs['experiment']=cost(a['usage'])
save('costs.json',dict(usd=costs,inputPerMillion=.25,cachedPerMillion=.025,outputPerMillion=2,source='https://developers.openai.com/api/docs/models/gpt-5-mini',checked='2026-11-11',invoiceVerified=False))
gates=dict(completeCalls=a['completed']==112 and not a['failures'],integrity=not a['srcChanged'] and not a['frozenChanged'] and not a['trackedDiff'],zeroFalseAccepts=all(s[f'{p}/split']['FN']==0 for p in ['tuning','holdout','repeat']),zeroFalseRejects=all(s[f'{p}/split']['FP']==0 for p in ['tuning','holdout','repeat']),allSpecialistDiagnoses=all(q[c]['allThree']==q[c]['total'] for c in ['source','editorial']),repeatCombined=read('stability.json')['split']==dict(agree=4,n=4),familySuperiority=all(v['wins']>=5 and v['losses']==0 for v in a['familyComparisons'].values()))
save('gates.json',dict(decision='GO' if all(gates.values()) else 'NO-GO',gates=gates,independentHumanReview=False,conditionalPhasesSkipped=['production implementation','new C# tests','full live Idea Agent repair acceptance'],reason='Critical v4 errors missed, correct idea rejected, diagnoses add requirements; no persuasive superiority.'))
assert not all(gates.values()),'GO needs separate implementation workflow'
# Comparable headline metrics use full labels; score.py additionally reports remit-adjusted specialist results.
overall=[]
for cond in ['source','editorial']:
 c=collections.Counter()
 for p in ['tuning','holdout']:
  cases=json.loads((R/p/'cases.json').read_text())
  for x in cases:
   v=json.loads((R/'runs'/p/f'{cond}-{x["id"]}.verdict.json').read_text());e=x['expectedAccepted'];b=v['accepted']
   c['TN' if e and b else 'FP' if e else 'FN' if b else 'TP']+=1
 overall.append(dict(condition=cond,**c))
save('specialist-full-labels.json',overall)
ensemble=[]
for cond in ['baseline','v2']:
 for id in ['005-b','010-b','v4-005-original','v4-010-original']:
  rs=[r for r in rows if r['condition']==cond and r['id']==id and r['phase'] in ['tuning','repeat']]
  ensemble.append(dict(condition=cond,id=id,calls=2,accepted=all(r['accepted'] for r in rs)))
save('equal-budget-repeat-ensembles.json',ensemble)
lines=['# Twee gespecialiseerde Idea-judges — eindrapport','', '**11 november 2026 · HEAD `f894d2f161e034aa514a7ce138eb2ba278b3cffe` · NO-GO.** De experimentele splitsing levert op deze set één extra detectie én één extra foutieve afwijzing. De oorspronkelijke v4-005 en v4-010 worden door beide specialisten geaccepteerd, ook bij herhaling. Productiecode, tests en productieprompts zijn intact. Geen commit of push.','', '## Vraag en uitgevoerde architectuurproef','', 'Twee afzonderlijke GPT-5-mini-calls beoordelen dezelfde ongewijzigde bron en het geselecteerde idee: Source Fidelity (feiten, causaliteit, bewijs, voorwaarden, zekerheid, motieven en interventie-effect) en Editorial Intent (bedoeling, doelgroep, centrale taak en koers). De experimentele combinatie accepteert uitsluitend bij twee geldige akkoorden. De vergelijkingscondities zijn de actuele productieprompt en exact v2 kandidaat 2. Iedere conditie gebruikt het bestaande C#-harnas en daarmee dezelfde productieparser, schema en Chat Completions-adapter. Per call een nieuw proces en agentsessie; geen eerdere diagnoses, labels of andere cases in de invoer. Beide specialisten worden altijd aangeroepen.','', 'Dit is een test van afzonderlijke AI-beoordelingen met een experimentele combinatie in de scoringslaag. Er zijn geen productieklassen SourceFidelityJudge, EditorialIntentJudge of IdeaValidationCoordinator geïmplementeerd: de voorafgaande kwaliteitsgate faalt. Bij GO zou de algemene IdeaSemanticJudge daadwerkelijk door die drie klassen zijn vervangen via Copilot CLI, inclusief wiring en tests. Alleen prompts omzetten was niet de beoogde productiewijziging.','', '## Protocol en beperkingen','', 'Het [protocol](protocol.md), één promptpaar, labels, bronnen, harnas en uitvoer-/scorescripts zijn vóór de eerste betaalde call bevroren in [frozen.json](verification/frozen.json). Er is geen tweede kandidaat, herselectie of optimalisatie na resultaten. Acht historische gevallen gebruiken v1/v2/v4 uitsluitend als regressie: 005 en 010 minimale paren, beide originele v4-ideeën en goede tegenvoorbeelden. Zestien nieuwe synthetische holdoutgevallen omvatten acht paren: lockers, kiln, hall, orchard, pool, bursary, nightbus en roof. Vier moeilijke negatieve regressiegevallen zijn eenmaal herhaald onder iedere conditie.','', '**Geen onafhankelijke menselijke beoordeling beschikbaar.** Dezelfde auteur maakte prompts, synthetische bronnen en labels en beoordeelde de diagnoses. Labels werden vooraf bevroren; diagnosebeoordeling is niet geblindeerd. De holdout is nieuw ten opzichte van eerdere experimenten, maar niet onafhankelijk samengesteld of extern geverifieerd. De korte bronnen bevatten vaak expliciete uitsluitingen; alle drie hoofdcondities halen 16/16. Dat maakt de set onvoldoende onderscheidend voor de subtiele problemen in de langere rapportbronnen. Acht historische case-ID’s delen twee bronfamilies en goede ideeobjecten; de holdout heeft acht families, geen zestien onafhankelijke bronnen.','', 'GO vereiste nul gecombineerde false accepts/rejects over alle fasen, echte diagnose van alle kritieke fouten, 100% brongetrouwe niet-voorschrijvende blockers, stabiele herhalingen en overtuigende verbetering tegenover beide comparators (minstens vijf gunstige en nul ongunstige familiediscordanties). Die poort is conservatief en kan met deze kleine set moeilijk overtuigend bewijs leveren. Het no-go berust daarnaast op concrete kritieke fouten en een false reject, onafhankelijk van statistische strengheid.','', '## Detectie','', 'Positief = materiële fout. FN = false accept; FP = false reject. Unique telt tuning plus holdout eenmaal, zonder herhalingen.','', '| Set | Conditie | TP | FP | TN | FN | Recall | Precision |','|---|---|---:|---:|---:|---:|---:|---:|']
for phase in ['tuning','holdout','repeat','unique']:
 for cond in ['baseline','v2','split']:
  v=s[phase+'/'+cond];lines.append(f'| {phase} | {cond} | {v["TP"]} | {v["FP"]} | {v["TN"]} | {v["FN"]} | {v["recall"]:.1%} | {v["precision"]:.1%} |')
lines+=['', 'De combinatie heeft op 24 case-ID’s 21 correcte verdicts, net als beide comparators: één minder false accept gaat samen met één extra false reject. Dit is geen aantoonbare betrouwbaarheidswinst. Op familiegroepen: versus productie één winst, één verlies, acht gelijke; eenzijdige sign-test p=0,75. Versus v2 tien gelijke families, p=1. De families zijn klein, synthetisch en niet willekeurig bemonsterd; deze p-waarden zijn beschrijvend, geen brede productiereliability.','', 'Afzonderlijke specialisten, met de volledige gecombineerde labels als referentie:','', '| Specialist | TP | FP | TN | FN |','|---|---:|---:|---:|---:|']
for v in overall:lines.append('| '+v['condition']+' | '+' | '.join(str(v.get(k,0)) for k in ['TP','FP','TN','FN'])+' |')
lines+=['', 'De [scores](verification/summary.json) tonen aanvullend de vooraf bedoelde remitlabels voor de holdout: Source Fidelity 6 TP, 2 buiten-remitblokkades, 8 TN, 0 FN; Editorial Intent 3 TP, 5 buiten-remitblokkades, 8 TN, 0 FN. Deze buiten-remitblokkades zijn geen false rejects van inhoudelijk goede ideeën: het zijn blokkades van fouten die aan de andere specialist waren toegewezen. De beperkte taakgrens wordt dus niet betrouwbaar gevolgd. De gecombineerde false reject is het goede historische v4-005-idee. De specialisten zijn ook niet onafhankelijk in statistische zin: dezelfde modelfamilie, bron en overlappende regels.','', '## Kritieke fouten en stabiliteit','', '- Originele v4-005: beide specialisten accepteren tweemaal het idee dat de prompttoevoeging de verschuiving veroorzaakte/kan verergeren, ondanks de beperkingen rond tijdstip, backendvariatie en attributie.','- Originele v4-010: beide specialisten accepteren tweemaal het vooraf kiezen van Narrative en de claim van hoogste onmiddellijke opbrengst, terwijl de bron de concrete case en feitelijke upstream-invoer bepalend maakt.','- Het minimale 005-b wordt aanvankelijk door Editorial Intent geblokkeerd terwijl Source Fidelity accepteert; bij herhaling gebeurt precies het omgekeerde. Het combinatieverdict blijft gelijk en verbergt daardoor instabiliteit.','- Het goede v4-005-idee wordt door Editorial Intent afgewezen omdat het niet alle promotiegronden opsomt. De rationale beweert nergens dat orchestration de enige grond was; de description kondigt juist uitleg van vergelijking en niet-promotie aan. Dit is een verzonnen volledigheidseis.','', 'Verdictovereenstemming eerste meting/herhaling: productie 4/4, v2 4/4, Source Fidelity 2/4, Editorial Intent 3/4, combinatie 4/4. Combinatiestabiliteit omvat twee herhaald gemiste originele fouten; zij bewijst geen juistheid. Er is maar één herhaling per negatief geval en geen herhaling van goede holdouts.','', 'Een beperkte gelijk-callbudgetcontrole gebruikt twee algemene beoordelingen als reject-if-either-bloks-ensemble op dezelfde vier herhalingsgevallen: beide comparators detecteren 1/4 met acht calls; één splitmeting detecteert 2/4 met acht calls. Dit is een kleine negatieve subset zonder goede gevallen; geen bewijs over false rejects of algemene superioriteit. De hoofdvergelijking kost per idee één comparatorcall tegenover twee specialistcalls.','', '## Volledige diagnosekwaliteit','', 'Alle 48 blockers zijn naast de bevroren bron en het idee beoordeeld, ook duplicaten en extra diagnoses bij een verder terecht afgewezen idee. Een correcte kern met ongefundeerde extra eisen faalt. [Beoordeling per blocker](diagnoses.md) · [Machineleesbaar](verification/diagnosis-review.json).','', '| Conditie | Blockers | Reële mismatch | Volledig brongetrouw | Niet-voorschrijvend | Alle drie |','|---|---:|---:|---:|---:|---:|']
for cond in ['baseline','v2','source','editorial']:
 v=q[cond];lines.append('| '+cond+' | '+' | '.join(str(v[k]) for k in ['total','realMismatch','sourceFaithful','nonPrescriptive','allThree'])+' |')
lines+=['', 'De combinatie zou alle 24 specialistblockers doorgeven (inclusief overlappende diagnoses): 16/24 halen alle drie eisen. Een productiecoordinator zou nog deduplicatie en een veilige begrenzing moeten krijgen; deze implementatie is niet gebouwd vanwege no-go.','', 'Voorbeelden: Source Fidelity eist bij roof dat de tekst beide mogelijke oorzaken opneemt; het foutieve confirmed moet worden gediagnosticeerd zonder nieuwe verplichte inhoud. Editorial Intent eist bij bursary onder meer timing en noemt eligibility die niet in de bron staat. V2 eist in de herhaalde 010-b dat een korte ideebeschrijving alle proefcontroles opsomt.','', 'De strenge protocolregel verlangt declaratieve constraints. Daarom falen ook brongetrouwe imperatieven als Do not present en expliciete rewrite-aanwijzingen. Declaratieve bronvoorwaarden met must/must not kunnen slagen. Dit taalkundige onderscheid is voor discussie vatbaar; ruimere scoring kan de diagnosepercentages verhogen. Het verandert de twee originele misses, verzonnen volledigheidseis en false reject niet. Geen antwoord bevat correction-fields; dat alleen waarborgt geen niet-voorschrijvende diagnose.','', '## Calls, tokens, kosten en logging','', '112/112 geplande judgecalls gereserveerd en voltooid, alle exitcodes nul en geldige verdicts; alias resolveerde steeds naar gpt-5-mini-2025-08-07. Geen vervangende calls, geen SDK-retries. Het totale plafond was vooraf 176: 112 judgecalls en 64 uitsluitend na GO voor de volledige feedbacklus. De 64 zijn ongebruikt gebleven en zijn niet herverdeeld. Eén niet-muteterende Copilot Haiku-probe staat apart in [inspection.md](inspection.md).','', '| Conditie | Calls | Input | Cached input | Output | Indicatie USD |','|---|---:|---:|---:|---:|---:|']
for cond in ['baseline','v2','source','editorial']:
 v=u[cond];lines.append(f'| {cond} | 28 | {v["inputTokenCount"]:,} | {v["cachedInputTokenCount"]:,} | {v["outputTokenCount"]:,} | ${costs[cond]:.4f} |')
lines +=['', f'Totaal **250.320 inputtokens** (156.416 cached), **84.527 outputtokens**, waarvan 74.624 reasoning (al onderdeel van output). Indicatie **${costs["experiment"]:.4f}**; de twee specialisten samen **${costs["split"]:.4f}**. Gebaseerd op op 11 november gecontroleerde [officiële OpenAI-prijzen](https://developers.openai.com/api/docs/models/gpt-5-mini): $0,25 input, $0,025 cached input en $2 output per miljoen tokens. Berekening trekt cached tokens eerst van input af; reasoning wordt niet dubbel geteld. Geen factuurcontrole, belasting, wisselkoers, Codex-abonnement of Copilot-credits meegerekend. Dit is een tariefindicatie, geen vastgestelde afschrijving.','', 'Per call zijn argumenten, reservering/start/eindtijd, exitcode, exacte bron/idee-JSON, ruwe verdicttekst, model-/response-ID en SDK-usage bewaard. [Ledger](verification/call-ledger.jsonl) · [Runs](runs/) · [Kostenberekening](verification/costs.json).','', '## Verificatie en besluit per fase','', '| Fase | Uitkomst |','|---|---|','| 1 Protocol, labels, budget en snapshots | Bevroren vóór calls; beperking onafhankelijke menselijke review expliciet |','| 2 Afzonderlijke en gecombineerde judges vergelijken | Alle 112 calls voltooid; één kandidaatpaar, geen optimalisatie |','| 3 Kwaliteitsgate | NO-GO: kritieke misses, false reject en diagnosefouten |','| 4 Productiearchitectuur via Copilot CLI | Bewust niet uitgevoerd wegens no-go |','| 5 Build en bestaande tests | Harnasbuild 0 fouten/waarschuwingen; 230 bestaande tests geslaagd |','| 6 Volledige live Idea Agent-feedbacklus | Niet uitgevoerd; go-voorwaarde ontbreekt. Zelfstandig herstel door specialisten blijft ongemeten |','| 7 Rapport en reproduceerbare artefacten | Voltooid; hervatbare ledger en integriteit opgeslagen |','', 'Offline 96 case/conditiecombinaties × acht contractantwoorden slagen: accept/reject, inconsistent accepted, vier blockers, oude correction-schema’s, lege velden, duplicaten en ontbrekende array. Dit test transport en bestaande parser; geen nieuwe productiecoordinator of live reparatie. De testreeks omvat 178 Application-, 21 Infrastructure- en 31 Console-tests, met bestaande echte MAF-integratie tegen fake clients. Domain had geen vindbare tests. [Build](verification/harness-build.txt) · [Tests](verification/tests.txt) · [Offline](verification/offline-log.txt).','', 'Alle bevroren bestanden en gecontroleerde src-bestanden behouden hun hashes; tracked diff is leeg en HEAD ongewijzigd. Het harnas is bytegelijk aan v2. Alleen deze nieuwe experimentmap is toegevoegd. [Integriteit](verification/final-integrity.json) · [Gates](verification/gates.json).','', '## Reproductie en hervatting','', 'Zie [inspection.md](inspection.md) voor runtime, CLI-verificatie en commando’s. Gebruik de gebundelde Python met -X utf8. De map bevat prepare.py (eenmalig vóór freeze), run.py, score.py, review.py, audit.py en finalize.py. Voor hervatten behoud je frozen.json, state.json en de ledger; reeds gereserveerde calls worden niet opnieuw verstuurd. De judgefase heeft nu nul resterende slots. Een verse reproductie vereist een nieuwe map op dezelfde diepte en een nieuw expliciet callbudget; reset de bestaande ledger niet. Labels en prompts blijven onveranderd.','', '**Concrete beslissing: niet implementeren en niet promoveren.** Dit ene bevroren specialistpaar is op GPT-5-mini onvoldoende betrouwbaar. De uitkomst verwerpt geen enkele denkbare specialistarchitectuur, maar rechtvaardigt deze productiewijziging niet. Er is geen tweede promptkandidaat gestart om de gate achteraf alsnog te halen. Een volgende proef zou eerst onafhankelijk gelabelde, langere en minder expliciete casussen nodig hebben; dat is vervolgwerk, niet uitgevoerd binnen dit traject.']
(R/'report.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
